+#[test]
+fn http_generation_config_does_not_manage_an_engine() {
+    let cli = Cli::try_parse_from([
+        "vllm-rs",
+        "serve",
+        "test-model",
+        "--generation-url",
+        "http://gateway:8080",
+        "--max-model-len",
+        "4096",
+    ])
+    .unwrap();
+    let Command::Serve(args) = cli.command else {
+        panic!("serve args")
+    };
+    let config = args.to_http_frontend_config(args.generation_url.clone().unwrap()).unwrap();
+    config.validate().unwrap();
+    assert!(!config.manages_engine);
+    assert_eq!(config.engine_count(), 0);
+    assert!(config.effective_coordinator_mode(true).is_none());
+    assert!(matches!(
+        config.engine_backend,
+        EngineBackend::HttpGenerate {
+            max_model_len: 4096,
+            ..
+        }
+    ));
+    assert!(
+        Cli::try_parse_from([
+            "vllm-rs",
+            "serve",
+            "test-model",
+            "--generation-url",
+            "http://gateway:8080",
+        ])
+        .is_err()
+    );
+}
+
+#[test]
+fn http_generation_rejects_invalid_context_limits() {
+    for limit in ["0", "auto"] {
+        let cli = Cli::try_parse_from([
+            "vllm-rs",
+            "serve",
+            "test-model",
+            "--generation-url",
+            "http://gateway:8080",
+            "--max-model-len",
+            limit,
+        ])
+        .unwrap();
+        let Command::Serve(args) = cli.command else {
+            panic!("serve args")
+        };
+        let error = args
+            .to_http_frontend_config(args.generation_url.clone().unwrap())
+            .and_then(|config| config.validate())
+            .unwrap_err();
+        assert!(
+            format!("{error:#}").contains("--max-model-len"),
+            "{error:#}"
+        );
+    }
+}
